import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static void bitAdd(long[] t, int i, long x) {
        int n = t.length - 1;
        for (; i <= n; i += i & -i) t[i] += x;
    }

    static long bitSum(long[] t, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[][] qs = new long[(int) q][3];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        long[] pk = new long[(int) n];
        for (int i = 0; i < n; i++) pk[i] = (a[i] << 17) | i;
        Arrays.sort(pk);
        long[] qk = new long[(int) q];
        for (int j = 0; j < q; j++) qk[j] = (qs[j][2] << 17) | j;
        Arrays.sort(qk);
        long[] t = new long[(int) n + 1];
        long[] ans = new long[(int) q];
        int p = 0;
        for (int k = 0; k < q; k++) {
            int j = (int) (qk[k] & 131071);
            long x = qs[j][2];
            while (p < n && (pk[p] >> 17) <= x) {
                bitAdd(t, (int) (pk[p] & 131071) + 1, 1);
                p++;
            }
            ans[j] = bitSum(t, (int) qs[j][1]) - bitSum(t, (int) qs[j][0] - 1);
        }
        StringBuilder out = new StringBuilder();
        for (int j = 0; j < q; j++) {
            if (j > 0) out.append(" ");
            out.append(ans[j]);
        }
        System.out.println(out);
    }
}
